const maturityModelCostRows = `-- name: MaturityModelCostRows :many
SELECT
    (tu.created_at AT TIME ZONE 'Asia/Shanghai')::date AS bucket_date,
    LOWER(tu.provider) AS provider,
    tu.model,
    SUM(tu.input_tokens)::bigint       AS input_tokens,
    SUM(tu.output_tokens)::bigint      AS output_tokens,
    SUM(tu.cache_read_tokens)::bigint  AS cache_read_tokens,
    SUM(tu.cache_write_tokens)::bigint AS cache_write_tokens,
    COALESCE(SUM(tu.cost_usd_ticks), 0)::bigint AS cost_usd_ticks,
    COALESCE(SUM(tu.input_tokens)       FILTER (WHERE tu.cost_usd_ticks IS NULL), 0)::bigint AS uncosted_input_tokens,
    COALESCE(SUM(tu.output_tokens)      FILTER (WHERE tu.cost_usd_ticks IS NULL), 0)::bigint AS uncosted_output_tokens,
    COALESCE(SUM(tu.cache_read_tokens)  FILTER (WHERE tu.cost_usd_ticks IS NULL), 0)::bigint AS uncosted_cache_read_tokens,
    COALESCE(SUM(tu.cache_write_tokens) FILTER (WHERE tu.cost_usd_ticks IS NULL), 0)::bigint AS uncosted_cache_write_tokens,
    count(*)::bigint AS usage_rows,
    count(tu.cost_usd_ticks)::bigint AS authoritative_rows
FROM task_usage tu
JOIN agent_task_queue q ON q.id = tu.task_id
JOIN agent a ON a.id = q.agent_id AND a.workspace_id = $1::uuid
WHERE tu.created_at >= $2::timestamptz
  AND tu.created_at <  $3::timestamptz
GROUP BY (tu.created_at AT TIME ZONE 'Asia/Shanghai')::date, LOWER(tu.provider), tu.model
ORDER BY bucket_date, LOWER(tu.provider), tu.model
`

type MaturityModelCostRowsParams struct {
	WorkspaceID pgtype.UUID        `json:"workspace_id"`
	FromUtc     pgtype.Timestamptz `json:"from_utc"`
	ToUtc       pgtype.Timestamptz `json:"to_utc"`
}

type MaturityModelCostRowsRow struct {
	BucketDate               pgtype.Date `json:"bucket_date"`
	Provider                 string      `json:"provider"`
	Model                    string      `json:"model"`
	InputTokens              int64       `json:"input_tokens"`
	OutputTokens             int64       `json:"output_tokens"`
	CacheReadTokens          int64       `json:"cache_read_tokens"`
	CacheWriteTokens         int64       `json:"cache_write_tokens"`
	CostUsdTicks             int64       `json:"cost_usd_ticks"`
	UncostedInputTokens      int64       `json:"uncosted_input_tokens"`
	UncostedOutputTokens     int64       `json:"uncosted_output_tokens"`
	UncostedCacheReadTokens  int64       `json:"uncosted_cache_read_tokens"`
	UncostedCacheWriteTokens int64       `json:"uncosted_cache_write_tokens"`
	UsageRows                int64       `json:"usage_rows"`
	AuthoritativeRows        int64       `json:"authoritative_rows"`
}

// Per-provider/model token totals for the model-detail trend (SDD §3.3).
// Uncosted* tokens are the NULL-cost subset only; callers price those from the
// generated price map and never re-price authoritative ticks (no double count).
func (q *Queries) MaturityModelCostRows(ctx context.Context, arg MaturityModelCostRowsParams) ([]MaturityModelCostRowsRow, error) {
	rows, err := q.db.Query(ctx, maturityModelCostRows, arg.WorkspaceID, arg.FromUtc, arg.ToUtc)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MaturityModelCostRowsRow{}
	for rows.Next() {
		var i MaturityModelCostRowsRow
		if err := rows.Scan(
			&i.BucketDate,
			&i.Provider,
			&i.Model,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CacheReadTokens,
			&i.CacheWriteTokens,
			&i.CostUsdTicks,
			&i.UncostedInputTokens,
			&i.UncostedOutputTokens,
			&i.UncostedCacheReadTokens,
			&i.UncostedCacheWriteTokens,
			&i.UsageRows,
			&i.AuthoritativeRows,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

