const maturityRetryablePlans = `-- name: MaturityRetryablePlans :many
SELECT plan_time
FROM sys_cron_executions
WHERE job_name = 'maturity_snapshot'
  AND scope_kind = 'global'
  AND scope_id = 'global'
  AND status = 'FAILED'
  AND attempt < max_attempts
  AND next_retry_at <= $1
  AND plan_time > $2
ORDER BY plan_time ASC
LIMIT 7
`

